from machine import Pin, I2C

class _MockFrameBuffer:
    """Minimal pure-Python FrameBuffer fallback when MicroPython ``framebuf`` is unavailable."""

    def __init__(self, width, height):
        self.width = width
        self.height = height
        self._ops = []

    def fill(self, color):
        self._ops.append(("fill", color))

    def text(self, string, x, y, color=1):
        self._ops.append(("text", string, x, y, color))

    def pixel(self, x, y, color=1):
        self._ops.append(("pixel", x, y, color))

    def hline(self, x, y, w, color=1):
        self._ops.append(("hline", x, y, w, color))

    def vline(self, x, y, h, color=1):
        self._ops.append(("vline", x, y, h, color))

    def line(self, x1, y1, x2, y2, color=1):
        self._ops.append(("line", x1, y1, x2, y2, color))

    def rect(self, x, y, w, h, color=1):
        self._ops.append(("rect", x, y, w, h, color))

    def fill_rect(self, x, y, w, h, color=1):
        self._ops.append(("fill_rect", x, y, w, h, color))


_I2C0_SDA = (0, 4, 8, 12, 16, 20)
_I2C0_SCL = (1, 5, 9, 13, 17, 21)
_I2C1_SDA = (2, 6, 10, 14, 18, 26)
_I2C1_SCL = (3, 7, 11, 15, 19, 27)


def _detect_i2c_id(scl, sda):
    """Infer RP2040 hardware I2C peripheral ID from GPIO pin numbers."""
    if sda in _I2C0_SDA and scl in _I2C0_SCL:
        return 0
    if sda in _I2C1_SDA and scl in _I2C1_SCL:
        return 1
    raise ValueError(
        "Pins (sda=GP{}, scl=GP{}) do not match a valid RP2040 hardware I2C pair. "
        "Pass i2c_id explicitly or use I2C0 (SDA in {}, SCL in {}) or "
        "I2C1 (SDA in {}, SCL in {}).".format(
            sda, scl, _I2C0_SDA, _I2C0_SCL, _I2C1_SDA, _I2C1_SCL
        )
    )


class OLED:
    """
    Represents an I2C monochrome OLED display (SSD1306 or SH1106).

    Operates natively at 3.3V logic and is safe for direct connection to
    Raspberry Pi Pico GPIO pins without a logic level shifter.

    :param int scl:
        The GPIO pin number connected to the OLED SCL pin. Defaults to ``3`` (GP3, I2C1).
    :param int sda:
        The GPIO pin number connected to the OLED SDA pin. Defaults to ``2`` (GP2, I2C1).
    :param int width:
        Display width in pixels. Defaults to ``128``.
    :param int height:
        Display height in pixels (must be a positive multiple of 8). Defaults to ``64``.
    :param int i2c_id:
        RP2040 I2C peripheral ID (``0`` or ``1``). If :data:`None` (default),
        inferred automatically from ``scl`` and ``sda``.
    :param int addr:
        7-bit I2C slave address. Defaults to ``0x3C``.
    :param str driver:
        Controller IC: ``"ssd1306"`` (default, typical 0.96") or ``"sh1106"``
        (typical 1.3").
    :param int freq:
        I2C bus frequency in Hz. Defaults to ``400000``.
    """

    def __init__(
        self,
        scl=3,
        sda=2,
        width=128,
        height=64,
        i2c_id=None,
        addr=0x3C,
        driver="ssd1306",
        freq=400000,
    ):
        driver_norm = str(driver).lower()
        if driver_norm not in ("ssd1306", "sh1106"):
            raise ValueError(
                "Unsupported OLED driver '{}'. Use 'ssd1306' or 'sh1106'.".format(
                    driver
                )
            )
        if width <= 0 or height <= 0 or height % 8 != 0:
            raise ValueError(
                "OLED dimensions must be positive and height a multiple of 8."
            )

        if i2c_id is None:
            i2c_id = _detect_i2c_id(scl, sda)

        self.width = width
        self.height = height
        self.pages = height // 8
        self.addr = addr
        self.driver = driver_norm
        self.i2c_id = i2c_id
        self.i2c = I2C(i2c_id, sda=Pin(sda), scl=Pin(scl), freq=freq)
        self.buffer = bytearray(self.pages * self.width)

        try:
            import framebuf

            self.fb = framebuf.FrameBuffer(
                self.buffer, self.width, self.height, framebuf.MONO_VLSB
            )
        except ImportError:
            self.fb = _MockFrameBuffer(self.width, self.height)

        self._init_display()

    def _write_cmd(self, cmd):
        self.i2c.writeto(self.addr, bytearray([0x80, cmd & 0xFF]))

    def _write_data(self, buf):
        self.i2c.writeto(self.addr, b"\x40" + bytes(buf))

    def _init_display(self):
        cmds = [
            0xAE,
            0xD5, 0x80,
            0xA8, self.height - 1,
            0xD3, 0x00,
            0x40,
        ]
        if self.driver == "ssd1306":
            cmds.extend([0x8D, 0x14, 0x20, 0x00])
        else:
            cmds.extend([0xAD, 0x8B])
        cmds.extend([
            0xA1,
            0xC8,
            0xDA, 0x02 if (self.width == 128 and self.height == 32) else 0x12,
            0x81, 0xCF,
            0xD9, 0xF1,
            0xDB, 0x40,
            0xA4,
            0xA6,
            0xAF,
        ])
        for cmd in cmds:
            self._write_cmd(cmd)
        self.clear()
        self.show()

    def clear(self, color=0):
        """Clear the display buffer (call :meth:`show` to update the screen)."""
        self.fb.fill(color)

    def fill(self, color):
        """Fill the entire display buffer with ``color`` (``0`` or ``1``)."""
        self.fb.fill(color)

    def text(self, string, x=0, y=0, color=1):
        """Draw a text string at ``(x, y)`` (call :meth:`show` to update the screen)."""
        self.fb.text(str(string), x, y, color)

    def pixel(self, x, y, color=1):
        """Set pixel at ``(x, y)`` to ``color`` (``0`` or ``1``)."""
        self.fb.pixel(x, y, color)

    def hline(self, x, y, w, color=1):
        """Draw a horizontal line starting at ``(x, y)`` with width ``w``."""
        self.fb.hline(x, y, w, color)

    def vline(self, x, y, h, color=1):
        """Draw a vertical line starting at ``(x, y)`` with height ``h``."""
        self.fb.vline(x, y, h, color)

    def line(self, x1, y1, x2, y2, color=1):
        """Draw a line from ``(x1, y1)`` to ``(x2, y2)``."""
        self.fb.line(x1, y1, x2, y2, color)

    def rect(self, x, y, w, h, color=1, fill=False):
        """Draw a rectangle at ``(x, y)`` with size ``(w, h)``."""
        if fill:
            self.fb.fill_rect(x, y, w, h, color)
        else:
            self.fb.rect(x, y, w, h, color)

    def contrast(self, value):
        """Adjust display contrast (``0``–``255``)."""
        self._write_cmd(0x81)
        self._write_cmd(value & 0xFF)

    def invert(self, invert=True):
        """Invert display colours when ``invert`` is :data:`True`."""
        self._write_cmd(0xA7 if invert else 0xA6)

    def poweroff(self):
        """Turn the OLED display panel off (sleep mode)."""
        self._write_cmd(0xAE)

    def poweron(self):
        """Turn the OLED display panel back on."""
        self._write_cmd(0xAF)

    def show(self):
        """Write the local framebuffer contents to the OLED display."""
        if self.driver == "ssd1306":
            for cmd in (0x21, 0, self.width - 1, 0x22, 0, self.pages - 1):
                self._write_cmd(cmd)
            self._write_data(self.buffer)
        else:
            for page in range(self.pages):
                self._write_cmd(0xB0 | page)
                self._write_cmd(0x02)
                self._write_cmd(0x10)
                start = page * self.width
                self._write_data(self.buffer[start : start + self.width])
